module.onRender:
// Module renderer options
// id: The id of the widget
// target: The target element to render
// properties: The properties for the widget
//
// NB: this widget intentionally has no <dataType>, so Xibo does NOT pass
// an `items` array to <onRender>. We never reference it; the stencil
// stays at its placeholder until the EventSource handler paints the
// first SSE frame.

(function () {
    'use strict';

    // ------------------------------------------------------------------
    // Structured logging helper.
    //
    // The bar-player snap is snap-confined Chromium with no DevTools and
    // a default sqlite log level of `error` only — there is no way to
    // observe widget JS at runtime from the operator side. This helper
    // always logs to the browser console (so the snap's console-logs.db
    // captures errors at minimum) AND best-effort pipes through
    // xiboIC.submitLog so the message lands in the CMS `log` table over
    // XMDS, where an operator can SELECT them out via mysql in the CMS
    // pod. See docs/OPERATIONS.md for the query.
    //
    // Levels map to the xiboIC.submitLog 'level' enum (info|audit|error)
    // with `warn` folded into `info` (xiboIC has no warn level — the
    // category prefix in the message preserves the distinction for grep).
    // The category 'crowdaq' is consistent across all calls so a single
    // LIKE '%[crowdaq:%' query picks up every event.
    // ------------------------------------------------------------------
    function crowdaqLog(level, event, data) {
        var payload;
        try { payload = JSON.stringify(data || {}); }
        catch (e) { payload = '{"_unserializable":true}'; }
        var msg = '[crowdaq:' + event + '] ' + payload;
        try {
            // eslint-disable-next-line no-console
            if (level === 'error') { console.error(msg); }
            // eslint-disable-next-line no-console
            else if (level === 'warn') { console.warn(msg); }
            // eslint-disable-next-line no-console
            else { console.log(msg); }
        } catch (e) { /* console may be missing in very old runtimes */ }
        try {
            if (typeof xiboIC !== 'undefined' && xiboIC && typeof xiboIC.submitLog === 'function') {
                // xiboIC.submitLog accepts info|audit|error. Map warn->info.
                var icLevel = (level === 'error') ? 'error'
                            : (level === 'audit') ? 'audit'
                            : 'info';
                xiboIC.submitLog({ category: 'crowdaq', level: icLevel, message: msg });
            }
        } catch (e) { /* swallow — never let logging take down the widget */ }
    }

    // Capture uncaught errors in this widget's frame so they reach the
    // CMS log. The widget runs inside a Chromium iframe with no DevTools
    // exposed, so without these handlers a thrown error inside an event
    // handler would be invisible from the operator side.
    if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
        window.addEventListener('error', function (e) {
            try {
                crowdaqLog('error', 'js-error', {
                    message: e && e.message,
                    source: e && e.filename,
                    lineno: e && e.lineno,
                    colno: e && e.colno,
                    stack: (e && e.error && typeof e.error.stack === 'string')
                        ? e.error.stack.substring(0, 500)
                        : null
                });
            } catch (err) { /* swallow */ }
        });
        window.addEventListener('unhandledrejection', function (e) {
            try {
                var reason = (e && e.reason != null) ? String(e.reason) : '';
                crowdaqLog('error', 'js-promise-reject', {
                    reason: reason.substring(0, 500)
                });
            } catch (err) { /* swallow */ }
        });
    }

    var $target = (typeof $ === 'function') ? $(target) : null;
    var $root = $target ? $target.find('[data-crowdaq-root]') : null;
    if (!$root || $root.length === 0) {
        crowdaqLog('error', 'init-no-root', {});
        return;
    }
    var rootEl = $root.get(0);

    var props = properties || {};
    var refreshInterval = parseInt(props.refreshInterval, 10);
    if (isNaN(refreshInterval) || refreshInterval < 5) { refreshInterval = 30; }
    var showTeamLogos = !!props.showTeamLogos;
    var showLastMoment = !!props.showLastMoment;
    var maxMomentLength = parseInt(props.maxMomentLength, 10);
    if (isNaN(maxMomentLength) || maxMomentLength <= 0) { maxMomentLength = 80; }

    // Replay speed multiplier passed to the backend SSE endpoint.
    // Clock interpolation between server events scales wall-clock time
    // by this factor so the on-screen minute display ticks at the same
    // rate the recording is being replayed at. Kept in sync with the
    // value baked into connect()'s URL builder below.
    var SPEED_MULTIPLIER = 10;

    // Resolve the API base URL: explicit property first, then the
    // bar-player bootstrap global. Per-widget settings win so an
    // operator can point a single bar at a different backend.
    var apiBaseUrlRaw = (typeof props.apiBaseUrl === 'string' ? props.apiBaseUrl : '').trim();
    var eventIdRaw = (typeof props.eventId === 'string' ? props.eventId : '').trim();

    // Multi-bar targeting: values of the form "display:<field>" are
    // resolved at render time against the player's xiboIC.info()
    // response. Supported fields (4.4.2): hardwareKey, displayName,
    // timeZone, latitude, longitude. See docs/TARGETING.md.
    // Xibo 4.4.2 does NOT expose the display's tag list to widgets
    // (xiboIC has no getDisplayTags and /info does not return tags —
    // see xibosignage/xibo-interactive-control README); the stable
    // primitive operators get is displayName. Encode the CROWDAQ event
    // id in displayName when you want one layout to serve many bars.
    var DISPLAY_FIELD_ALLOWLIST = {
        hardwareKey: 1,
        displayName: 1,
        timeZone: 1,
        latitude: 1,
        longitude: 1
    };
    var DISPLAY_PREFIX = 'display:';
    function needsDisplayResolution(value) {
        return typeof value === 'string' && value.indexOf(DISPLAY_PREFIX) === 0;
    }
    function parseDisplayField(value) {
        return value.slice(DISPLAY_PREFIX.length);
    }
    function resolveFromInfo(value, info) {
        if (!needsDisplayResolution(value)) { return value; }
        var field = parseDisplayField(value);
        if (!DISPLAY_FIELD_ALLOWLIST[field]) { return ''; }
        if (!info || typeof info !== 'object') { return ''; }
        var raw = info[field];
        if (raw == null) { return ''; }
        return String(raw);
    }

    // --- DOM helpers: selectors are data-attr based so Twig can rename
    //     classes without breaking the JS. ---
    function q(sel) { return rootEl.querySelector(sel); }
    function setText(sel, text) {
        var el = q(sel);
        if (el) { el.textContent = (text == null ? '' : String(text)); }
    }
    function setAttr(sel, attr, value) {
        var el = q(sel);
        if (el) { el.setAttribute(attr, value); }
    }
    function show(sel, visible) {
        var el = q(sel);
        if (!el) { return; }
        if (visible) { el.removeAttribute('hidden'); }
        else { el.setAttribute('hidden', ''); }
    }
    function truncate(text, maxLen) {
        if (typeof text !== 'string') { return ''; }
        if (text.length <= maxLen) { return text; }
        return text.slice(0, maxLen - 1) + '…';
    }

    // --- Status pill + error pill + stale overlay + lifecycle banner ---
    function setStatus(state, label) {
        setAttr('[data-crowdaq-status]', 'data-state', state);
        setText('[data-crowdaq-status]', label || state);
    }
    function showErrorPill(message) {
        var el = q('[data-crowdaq-error-pill]');
        if (!el) { return; }
        if (!message) {
            el.setAttribute('hidden', '');
            el.textContent = '';
            return;
        }
        el.textContent = message;
        el.removeAttribute('hidden');
    }
    function showStale(isStale) {
        if (isStale) { rootEl.classList.add('crowdaq-stale'); }
        else { rootEl.classList.remove('crowdaq-stale'); }
        show('[data-crowdaq-stale-overlay]', isStale);
    }
    // showLifecycleBanner: shows a banner with the given label.
    // When `transient` is truthy the banner auto-fades out after 3s
    // (used for "MATCH STARTED", "FULL TIME", "REPLAY LOOPING" etc).
    // For sustained states ("halftime", "pre-game") the banner stays
    // until the next status-change clears it.
    var lifecycleBannerTimer = null;
    function showLifecycleBanner(label, transient) {
        var el = q('[data-crowdaq-status-overlay]');
        if (!el) { return; }
        if (lifecycleBannerTimer) {
            clearTimeout(lifecycleBannerTimer);
            lifecycleBannerTimer = null;
        }
        el.classList.remove('crowdaq-status-overlay-fading');
        show('[data-crowdaq-status-overlay]', !!label);
        setText('[data-crowdaq-status-overlay-text]', label || '');
        if (label && transient) {
            lifecycleBannerTimer = setTimeout(function () {
                el.classList.add('crowdaq-status-overlay-fading');
                lifecycleBannerTimer = setTimeout(function () {
                    el.classList.remove('crowdaq-status-overlay-fading');
                    el.setAttribute('hidden', '');
                    setText('[data-crowdaq-status-overlay-text]', '');
                }, 320);
            }, 3000);
        }
    }
    function showReconnectingPill(visible) {
        show('[data-crowdaq-reconnecting-pill]', !!visible);
    }

    // --- Possession dot: highlight the team in current possession.
    //     Runs on each `possession-change` event AND on score-update
    //     payloads that include a `possession` field (the backend may
    //     piggyback it on score frames to save a round-trip). ---
    function setPossession(team) {
        var dots = rootEl.querySelectorAll('[data-crowdaq-possession-dot]');
        for (var i = 0; i < dots.length; i++) {
            var dot = dots[i];
            if (team && dot.getAttribute('data-team') === team) {
                dot.removeAttribute('hidden');
            } else {
                dot.setAttribute('hidden', '');
            }
        }
    }

    // --- Match clock: minute + period label (1H/HT/2H/ET/PEN/FT). ---
    function setClock(minute, period) {
        if (minute != null) {
            var minStr = (typeof minute === 'number') ? (minute + "'") : String(minute);
            setText('[data-crowdaq-clock-minute]', minStr);
        }
        if (period) { setText('[data-crowdaq-clock-period]', String(period)); }
    }

    // --- Local clock interpolation.
    //     The backend only emits `clock.minute` on score-update +
    //     status events, not on a steady cadence. Between events the
    //     on-screen clock would freeze, which reads as "feed dead" to
    //     a bar regular. To fix the dead-clock UX without changing
    //     the contract, the widget extrapolates the minute locally:
    //     every 250ms it computes `(now - baselineWallMs) *
    //     SPEED_MULTIPLIER + baselineMinute` (in minutes) and paints
    //     it. When the next server event lands, captureClockBaseline()
    //     resets the baseline so the local extrapolation stays anchored
    //     to the server's authoritative timestamp.
    //
    //     We only run interpolation while the clock is in a state
    //     that makes sense to advance (live / extra time / penalty).
    //     During halftime / pre-game / FT we hold the baseline. ---
    var clockBaselineWallMs = null;     // wall-clock ms when last server clock arrived
    var clockBaselineMinute = null;     // minute value at that baseline
    var clockRunning = false;           // gates interpolation
    var clockTickTimer = null;

    function captureClockBaseline(minute, _period) {
        if (typeof minute !== 'number' || isNaN(minute)) {
            // Period-only update with no minute: keep prior baseline.
            return;
        }
        clockBaselineWallMs = Date.now();
        clockBaselineMinute = minute;
    }
    function setClockRunning(running) {
        clockRunning = !!running;
        if (rootEl) {
            rootEl.setAttribute('data-crowdaq-clock-running', running ? '1' : '0');
        }
    }
    function tickClock() {
        if (!clockRunning) { return; }
        if (clockBaselineWallMs == null || clockBaselineMinute == null) { return; }
        var elapsedWallMs = Date.now() - clockBaselineWallMs;
        var elapsedMatchMin = (elapsedWallMs / 60000) * SPEED_MULTIPLIER;
        var displayMin = Math.floor(clockBaselineMinute + elapsedMatchMin);
        if (displayMin < 0) { displayMin = 0; }
        // Cap at 130' so a stuck baseline doesn't show 999' nonsense.
        if (displayMin > 130) { displayMin = 130; }
        setText('[data-crowdaq-clock-minute]', displayMin + "'");
    }

    // --- Team-logo handling with abbreviation fallback ---
    function setTeamLogo(selector, nameSelector, src, nameText, abbreviation) {
        var img = q(selector);
        if (!img) { return; }
        if (!showTeamLogos || !src) {
            img.setAttribute('hidden', '');
            img.removeAttribute('src');
            // Fallback to abbreviation when logos are disabled OR no url.
            setText(nameSelector, abbreviation || nameText || '');
            return;
        }
        img.onerror = function () {
            img.setAttribute('hidden', '');
            setText(nameSelector, abbreviation || nameText || '');
        };
        img.setAttribute('alt', nameText || '');
        img.setAttribute('src', src);
        img.removeAttribute('hidden');
        setText(nameSelector, abbreviation || nameText || '');
    }

    // --- score-update handler: full snapshot -> DOM ---
    // lastScore is initialised to 0 (not null) so the first SSE frame
    // that arrives with a non-zero score (replay restart, late-join)
    // still flashes the changed digit. The previous null-guard was
    // suppressing the very first goal flash and was the root cause of
    // the operator-reported "silent updates" UX gap. Repeated equal
    // scores (clock-only frames) do nothing.
    var lastScore = { home: 0, away: 0 };
    var lastMomentText = null;
    function onScoreUpdate(payload) {
        if (!payload || typeof payload !== 'object') { return; }
        var teams = payload.teams || {};
        var score = payload.score || {};
        var excitement = payload.excitement || {};
        var lastMoment = payload.last_moment || {};

        var homeTeam = teams.home || {};
        var awayTeam = teams.away || {};

        setTeamLogo(
            '[data-crowdaq-team-a-logo]',
            '[data-crowdaq-team-a]',
            homeTeam.logo_url,
            homeTeam.name,
            homeTeam.abbreviation
        );
        setTeamLogo(
            '[data-crowdaq-team-b-logo]',
            '[data-crowdaq-team-b]',
            awayTeam.logo_url,
            awayTeam.name,
            awayTeam.abbreviation
        );

        // deltaSinceLast flash on ANY change (up or back to 0 on
        // looping replay reset). lastScore is seeded at 0,0 so the
        // first non-zero frame flashes too.
        var newHome = (score.home != null) ? score.home : 0;
        var newAway = (score.away != null) ? score.away : 0;
        var homeChanged = newHome !== lastScore.home;
        var awayChanged = newAway !== lastScore.away;
        var anyScoreChange = homeChanged || awayChanged;
        if (homeChanged) { flash('[data-crowdaq-team-a-score]'); }
        if (awayChanged) { flash('[data-crowdaq-team-b-score]'); }
        lastScore.home = newHome;
        lastScore.away = newAway;
        setText('[data-crowdaq-team-a-score]', newHome);
        setText('[data-crowdaq-team-b-score]', newAway);

        // Excitement meter (level is 0..1 per contract).
        var level = parseFloat(excitement.level);
        if (isNaN(level)) { level = 0; }
        var clamped = Math.max(0, Math.min(1, level));
        var meterEl = q('[data-crowdaq-excitement-fill]');
        if (meterEl) { meterEl.style.width = (clamped * 100) + '%'; }
        setText('[data-crowdaq-excitement-value]', (clamped * 10).toFixed(1));
        setAttr('[data-crowdaq-excitement]', 'aria-valuenow', (clamped * 10).toFixed(1));
        var trend = excitement.trend || 'flat';
        var trendEl = q('[data-crowdaq-excitement-trend]');
        if (trendEl) {
            trendEl.setAttribute('data-trend', trend);
            trendEl.innerHTML = (trend === 'rising')
                ? '&#9650;'
                : (trend === 'falling' ? '&#9660;' : '&bull;');
        }

        // Last moment row — score-update carries the current summary.
        var newMomentText = (lastMoment && typeof lastMoment.text === 'string')
            ? lastMoment.text
            : null;
        if (showLastMoment && newMomentText !== null) {
            setText('[data-crowdaq-moment-text]', truncate(newMomentText, maxMomentLength));
        }

        // Goal-toast: a score change WITH a populated last_moment
        // (or a fresh moment text) is treated as a notable goal
        // event. Surfaces a 5s slide-in banner so the bar regulars
        // notice the moment a goal lands. We deliberately don't
        // toast on stand-alone `moment` events (handled separately
        // via onMoment) to avoid double-banners.
        if (anyScoreChange && newMomentText && newMomentText !== lastMomentText) {
            showGoalToast(newMomentText);
        }
        if (newMomentText !== null) { lastMomentText = newMomentText; }

        // Clock: minute + period when the payload carries them.
        // Backend-normalized SSE frames may also embed `elapsed`
        // (minutes since kickoff) at the top level — fall back to it
        // when no nested clock object is present.
        var clock = payload.clock;
        if (clock && typeof clock === 'object') {
            setClock(clock.minute, clock.period);
            captureClockBaseline(clock.minute, clock.period);
        } else if (payload.elapsed != null) {
            setClock(payload.elapsed, null);
            captureClockBaseline(payload.elapsed, null);
        }

        // Possession piggyback: backend may include `possession: 'home'|'away'|null`
        // on score-update frames so the widget doesn't need a separate
        // possession-change round-trip on first paint.
        if (Object.prototype.hasOwnProperty.call(payload, 'possession')) {
            setPossession(payload.possession);
        }
    }
    function flash(selector) {
        var el = q(selector);
        if (!el) { return; }
        // Force restart of the keyframe animation: removing then
        // re-adding the class in the same tick is debounced by the
        // browser to a no-op, so we toggle via a forced reflow.
        el.classList.remove('crowdaq-delta-flash');
        // eslint-disable-next-line no-unused-expressions
        void el.offsetWidth;
        el.classList.add('crowdaq-delta-flash');
        setTimeout(function () {
            if (el && el.classList) { el.classList.remove('crowdaq-delta-flash'); }
        }, 700);
    }

    // --- Goal toast: slide-down banner with the last_moment text.
    //     Auto-clears after 5s. If a second goal lands during the
    //     5s window, the timer is reset and the new text overwrites
    //     the banner — operator never sees a stale goal blurb on
    //     the strip. ---
    var goalToastTimer = null;
    function showGoalToast(text) {
        var el = q('[data-crowdaq-goal-toast]');
        var textEl = q('[data-crowdaq-goal-toast-text]');
        if (!el || !textEl) { return; }
        textEl.textContent = truncate(String(text || ''), maxMomentLength);
        el.removeAttribute('hidden');
        // Force reflow before adding the visible class so the slide-in
        // transition runs even when the toast was already hidden.
        // eslint-disable-next-line no-unused-expressions
        void el.offsetWidth;
        el.classList.add('crowdaq-goal-toast-visible');
        if (goalToastTimer) { clearTimeout(goalToastTimer); }
        goalToastTimer = setTimeout(function () {
            el.classList.remove('crowdaq-goal-toast-visible');
            // After the 0.35s slide-out transition, hide so it
            // doesn't intercept any future click interactions.
            setTimeout(function () { el.setAttribute('hidden', ''); }, 400);
        }, 5000);
    }

    // --- moment handler: standalone notable-moment text line ---
    function onMoment(payload) {
        if (!showLastMoment || !payload || typeof payload.description !== 'string') {
            return;
        }
        setText('[data-crowdaq-moment-text]', truncate(payload.description, maxMomentLength));
    }

    // --- status handler: lifecycle state banner.
    //     The backend may emit either {state: "..."} (contract shape)
    //     or {status: "..."} (legacy shape from the recorder); accept
    //     both for forward-compat.
    //
    //     Transition banners (transient: 3s auto-fade) vs sustained
    //     banners (held until next status):
    //       - transient: live (kickoff), final, looping
    //       - sustained: halftime, extra time, penalties, pre-game
    //
    //     Also gates clock interpolation: the local clock only
    //     extrapolates while the match is in a running state. ---
    var lastSeenStatus = null;
    function onStatus(payload) {
        if (!payload || typeof payload !== 'object') { return; }
        var state = (typeof payload.state === 'string')
            ? payload.state
            : (typeof payload.status === 'string' ? payload.status : null);
        if (!state) { return; }

        var prev = lastSeenStatus;
        lastSeenStatus = state;

        // Capture an initial clock baseline if the status payload
        // carries one (the recorder embeds {clock: {minute, period}}
        // on transitions). Without this the local interpolator can
        // sit at minute=null until the first score-update lands —
        // which on a 0-0 quiet match would leave the clock blank
        // for minutes.
        if (payload && payload.clock && typeof payload.clock === 'object') {
            captureClockBaseline(payload.clock.minute, payload.clock.period);
            if (typeof payload.clock.minute === 'number') {
                setClock(payload.clock.minute, payload.clock.period);
            }
        }

        // `looping` is the replay-loop transition: the backend has
        // played the recording to completion and is about to seek
        // back to minute 0. The widget MUST flush its in-memory
        // score / possession / clock state so the next frame paints
        // a fresh match, not a stale FT scoreline. (Per docs/contract
        // amendment v1.1.0: status enum gained `looping`.)
        if (state === 'looping') {
            resetMatchState();
            setClockRunning(false);
            showLifecycleBanner('REPLAY LOOPING', true);
            return;
        }

        // Drive clock-running gate by the new state.
        var isRunning = (state === 'live' || state === 'extra_time' || state === 'penalty_shootout');
        setClockRunning(isRunning);

        var label = '';
        var transient = false;
        switch (state) {
            case 'pre_game':         label = 'PRE-GAME'; break;
            case 'halftime':         label = 'HALFTIME'; break;
            case 'extra_time':       label = 'EXTRA TIME'; transient = (prev !== 'extra_time'); break;
            case 'penalty_shootout': label = 'PENALTIES'; transient = (prev !== 'penalty_shootout'); break;
            case 'final':            label = 'FULL TIME'; transient = true; break;
            case 'cancelled':        label = 'CANCELLED'; break;
            case 'postponed':        label = 'POSTPONED'; break;
            case 'live':
                // Show "MATCH STARTED" toast on the kickoff
                // transition (pre_game -> live or first observed
                // live state). On every subsequent live status
                // (e.g. resume from halftime) we surface a brief
                // "LIVE" toast so the operator gets a visible
                // confirmation that play has resumed.
                if (prev === null || prev === 'pre_game') {
                    label = 'MATCH STARTED'; transient = true;
                } else if (prev !== 'live') {
                    label = 'LIVE'; transient = true;
                } else {
                    label = '';
                }
                break;
            default:                 label = state;
        }
        showLifecycleBanner(label, transient);
    }

    // --- possession-change handler: dot moves to the team that just
    //     gained possession. Payload shape: {team: 'home'|'away'|null}. ---
    function onPossessionChange(payload) {
        if (!payload || typeof payload !== 'object') { return; }
        var team = payload.team;
        if (team === 'home' || team === 'away' || team === null) {
            setPossession(team);
        }
    }

    function resetMatchState() {
        lastScore = { home: 0, away: 0 };
        lastMomentText = null;
        setText('[data-crowdaq-team-a-score]', '0');
        setText('[data-crowdaq-team-b-score]', '0');
        setPossession(null);
        setClock(0, null);
        setText('[data-crowdaq-moment-text]', '');
        clockBaselineWallMs = Date.now();
        clockBaselineMinute = 0;
    }

    // --- heartbeat handler: track last receipt for the RECONNECTING
    //     pill watchdog (in addition to the resetStaleTimer() path
    //     which is handled uniformly by the SSE dispatcher), and
    //     pulse the LIVE pill so the operator gets a visible
    //     "still alive" tick every ~15s. ---
    var lastEventAt = Date.now();
    function onHeartbeat() {
        // resetStaleTimer() in the SSE dispatcher already runs.
        // Track lastEventAt explicitly so the reconnecting watchdog
        // can fire independently of the (longer) stale timer.
        var pillEl = q('[data-crowdaq-status]');
        if (pillEl) {
            pillEl.classList.remove('crowdaq-status-pulse');
            // Force reflow to restart the keyframe animation.
            // eslint-disable-next-line no-unused-expressions
            void pillEl.offsetWidth;
            pillEl.classList.add('crowdaq-status-pulse');
            setTimeout(function () {
                if (pillEl && pillEl.classList) {
                    pillEl.classList.remove('crowdaq-status-pulse');
                }
            }, 650);
        }
    }

    // --- error handler: show error pill + trigger reconnect ---
    function onStreamError(payload) {
        var msg = (payload && typeof payload.message === 'string')
            ? payload.message
            : (payload && payload.code ? String(payload.code) : 'stream error');
        showErrorPill(truncate(msg, 60));
        crowdaqLog('error', 'server-error-event', {
            code: (payload && payload.code) || null,
            message: String(msg).substring(0, 200)
        });
        scheduleReconnect();
    }

    // --- Stale timer ---
    var staleTimer = null;
    function resetStaleTimer() {
        if (staleTimer) { clearTimeout(staleTimer); }
        showStale(false);
        var staleMs = Math.max(10, refreshInterval * 2) * 1000;
        staleTimer = setTimeout(function () {
            showStale(true);
            setStatus('stale', 'stale');
            crowdaqLog('warn', 'stale-detected', {
                lastEventAt: lastEventAt,
                now: Date.now(),
                gapMs: Date.now() - lastEventAt,
                staleThresholdMs: staleMs
            });
        }, staleMs);
    }

    // --- Pre-stream paint: nothing to do.
    //     This widget is pure-client-side; there is no Xibo-side
    //     `items` array to seed the DOM (no <dataType>, no <sampleData>,
    //     no server-side data cache). The stencil's "Waiting for
    //     CROWDAQ feed…" placeholder stays on screen until the first
    //     SSE frame from openStream() lands. We guard with `typeof`
    //     anyway so that if Xibo ever does inject a legacy `items`
    //     binding from a cached layout, the JS doesn't ReferenceError. ---
    try {
        if (typeof items !== 'undefined' && Array.isArray(items) && items.length > 0) {
            onScoreUpdate(items[0]);
            setStatus('stale', 'cached');
        }
    } catch (e) { /* ignore — items not defined in client-side-only mode */ }

    // --- Resolved values, finalised once xiboIC.info() returns. ---
    var apiBaseUrl = '';
    var eventId = '';
    var url = '';

    crowdaqLog('info', 'init', {
        apiBaseUrlRaw: apiBaseUrlRaw,
        eventIdRaw: eventIdRaw,
        refreshInterval: refreshInterval,
        showTeamLogos: showTeamLogos,
        showLastMoment: showLastMoment,
        maxMomentLength: maxMomentLength,
        userAgent: (typeof navigator !== 'undefined' && navigator.userAgent) ? navigator.userAgent.substring(0, 200) : null,
        hasXiboIC: (typeof xiboIC !== 'undefined'),
        hasEventSource: (typeof EventSource !== 'undefined')
    });

    function applyResolution(rawApiBaseUrl, rawEventId, info) {
        // apiBaseUrl: resolve display:<field>, fall back to bootstrap
        // global, strip trailing slashes.
        var resolvedApi = needsDisplayResolution(rawApiBaseUrl)
            ? resolveFromInfo(rawApiBaseUrl, info)
            : rawApiBaseUrl;
        if (!resolvedApi && typeof window !== 'undefined' && window.crowdaqBackendBase) {
            resolvedApi = String(window.crowdaqBackendBase);
        }
        resolvedApi = String(resolvedApi || '').replace(/\/+$/, '');

        // eventId: resolve display:<field>, trim.
        var resolvedEvent = needsDisplayResolution(rawEventId)
            ? resolveFromInfo(rawEventId, info)
            : rawEventId;
        resolvedEvent = String(resolvedEvent || '').trim();

        apiBaseUrl = resolvedApi;
        eventId = resolvedEvent;

        // Mirror the resolved values onto the hidden debug elements so
        // operators / headless probes can introspect what a given bar
        // actually rendered with.
        setAttr('[data-crowdaq-resolved-api-base-url]', 'data-crowdaq-resolved-api-base-url', apiBaseUrl);
        setAttr('[data-crowdaq-resolved-event-id]', 'data-crowdaq-resolved-event-id', eventId);

        crowdaqLog('info', 'resolved', {
            apiBaseUrl: apiBaseUrl,
            eventId: eventId,
            sourceInfoPresent: !!info
        });
    }

    function isPreviewEnv() {
        if (typeof xiboIC === 'undefined') { return true; }
        try { return !!xiboIC.checkIsPreview(); }
        catch (e) { return true; }
    }

    function resolveProperties(done) {
        var needsInfo =
            needsDisplayResolution(apiBaseUrlRaw) ||
            needsDisplayResolution(eventIdRaw);

        if (!needsInfo || isPreviewEnv() || typeof xiboIC === 'undefined' || typeof xiboIC.info !== 'function') {
            // Editor / preview / no xiboIC: treat raw values as literals.
            // (In the CMS editor xiboIC.info would fail anyway; the
            // widget renders the placeholder stencil which is enough to
            // preview the layout.)
            applyResolution(apiBaseUrlRaw, eventIdRaw, null);
            done();
            return;
        }

        // Real player: mirror the canonical upstream pattern used by
        // modules/googletraffic.xml — xiboIC.info({done, error}) with a
        // JSON.parse on xhr.responseText.
        var finished = false;
        function finish(info) {
            if (finished) { return; }
            finished = true;
            applyResolution(apiBaseUrlRaw, eventIdRaw, info);
            done();
        }
        // Defensive timeout — if the local player server is wedged we
        // still want to render the placeholder instead of hanging.
        var safety = setTimeout(function () { finish(null); }, 5000);
        try {
            xiboIC.info({
                done: function (xhr) {
                    clearTimeout(safety);
                    var info = null;
                    try { info = JSON.parse(xhr.responseText); }
                    catch (e) { info = null; }
                    finish(info);
                },
                error: function () {
                    clearTimeout(safety);
                    finish(null);
                }
            });
        } catch (e) {
            clearTimeout(safety);
            finish(null);
        }
    }

    // --- Reconnect state ---
    var backoffSchedule = [1000, 2000, 5000, 15000, 30000];
    var attempt = 0;
    var MAX_ATTEMPTS = 5;
    var reconnectTimer = null;
    var source = null;
    var cleanedUp = false;

    function closeSource() {
        if (source) {
            try { source.close(); } catch (e) { /* ignore */ }
            source = null;
        }
    }
    function scheduleReconnect() {
        closeSource();
        if (cleanedUp) { return; }
        if (attempt >= MAX_ATTEMPTS) {
            setStatus('disconnected', 'offline');
            showStale(true);
            crowdaqLog('error', 'es-give-up', { attempts: attempt, maxAttempts: MAX_ATTEMPTS, url: url });
            return;
        }
        var delay = backoffSchedule[Math.min(attempt, backoffSchedule.length - 1)];
        attempt += 1;
        setStatus('disconnected', 'reconnecting');
        crowdaqLog('warn', 'reconnect-attempt', { attempt: attempt, backoffMs: delay, url: url });
        reconnectTimer = setTimeout(openStream, delay);
    }

    function openStream() {
        if (cleanedUp) { return; }
        setStatus('connecting', 'connecting');
        crowdaqLog('info', 'es-opening', { url: url, attempt: attempt });
        try {
            source = new EventSource(url);
        } catch (err) {
            setStatus('disconnected', 'offline');
            showErrorPill('open failed');
            crowdaqLog('error', 'es-open-throw', {
                url: url,
                error: String(err && err.message || err).substring(0, 300)
            });
            scheduleReconnect();
            return;
        }

        source.onopen = function (e) {
            attempt = 0;  // reset backoff on successful (re)connect
            setStatus('live', 'live');
            showErrorPill('');
            resetStaleTimer();
            crowdaqLog('info', 'es-open', {
                readyState: source ? source.readyState : null,
                url: url,
                eventType: e && e.type
            });
        };

        // Generic onerror: browser tried to reconnect natively; we take
        // over with bounded backoff so the widget stops thrashing after
        // MAX_ATTEMPTS. EventSource intentionally does not expose error
        // detail (CORS / network / 5xx all surface the same way) — we
        // capture readyState + url + the in-flight attempt counter so an
        // operator can correlate against the backend log.
        source.onerror = function (e) {
            crowdaqLog('error', 'es-error', {
                readyState: source ? source.readyState : null,
                url: url,
                attempt: attempt,
                eventType: e && e.type,
                timestamp: Date.now()
            });
            scheduleReconnect();
        };

        function listen(name, handler) {
            source.addEventListener(name, function (msg) {
                lastEventAt = Date.now();
                showReconnectingPill(false);
                resetStaleTimer();
                setStatus('live', 'live');
                showErrorPill('');
                var data = null;
                var rawLen = (msg && typeof msg.data === 'string') ? msg.data.length : 0;
                if (rawLen > 0) {
                    try { data = JSON.parse(msg.data); }
                    catch (err) {
                        crowdaqLog('error', 'es-parse-error', {
                            event: name,
                            error: String(err && err.message || err).substring(0, 200),
                            sample: (typeof msg.data === 'string') ? msg.data.substring(0, 120) : null
                        });
                        return;
                    }
                }
                crowdaqLog('info', 'es-event', {
                    event: name,
                    bytes: rawLen,
                    // Lightweight payload summary — full payload would
                    // bloat the CMS log table. Surface the fields that
                    // matter for debugging routing / state mismatches.
                    keys: data && typeof data === 'object' ? Object.keys(data).slice(0, 12) : null
                });
                try { handler(data); }
                catch (err) {
                    // never let a handler kill the stream
                    crowdaqLog('error', 'handler-throw', {
                        event: name,
                        error: String(err && err.message || err).substring(0, 200),
                        stack: (err && typeof err.stack === 'string') ? err.stack.substring(0, 400) : null
                    });
                }
            });
        }

        listen('score-update', onScoreUpdate);
        listen('possession-change', onPossessionChange);
        listen('moment', onMoment);
        listen('status', onStatus);
        listen('heartbeat', onHeartbeat);
        listen('error', onStreamError);
    }

    // --- Clock interpolation tick: 250ms cadence smooth-updates the
    //     on-screen minute display between server clock samples. The
    //     setClockRunning() gate (driven by status events) controls
    //     whether this writes to the DOM each tick. ---
    clockTickTimer = setInterval(function () {
        if (cleanedUp) { return; }
        try { tickClock(); }
        catch (e) { /* swallow */ }
    }, 250);

    // --- RECONNECTING pill watchdog: if no SSE event of any kind has
    //     arrived in 30s, surface a yellow "RECONNECTING…" pill. The
    //     stale-timer path covers a longer 2*refreshInterval window;
    //     this is the early-warning indicator the contract documents. ---
    var watchdogPillVisible = false;
    var reconnectWatchdog = setInterval(function () {
        if (cleanedUp) { return; }
        var gap = Date.now() - lastEventAt;
        if (gap > 30000) {
            if (!watchdogPillVisible) {
                watchdogPillVisible = true;
                crowdaqLog('warn', 'watchdog-no-events', {
                    gapMs: gap,
                    lastEventAt: lastEventAt,
                    readyState: source ? source.readyState : null
                });
            }
            showReconnectingPill(true);
        } else if (watchdogPillVisible && gap < 5000) {
            // Reset the latch once events resume so a future stall logs again.
            watchdogPillVisible = false;
        }
    }, 5000);

    // --- Cleanup on unload / widget replacement ---
    function cleanup() {
        cleanedUp = true;
        if (reconnectTimer) { clearTimeout(reconnectTimer); reconnectTimer = null; }
        if (staleTimer) { clearTimeout(staleTimer); staleTimer = null; }
        if (reconnectWatchdog) { clearInterval(reconnectWatchdog); reconnectWatchdog = null; }
        if (clockTickTimer) { clearInterval(clockTickTimer); clockTickTimer = null; }
        if (lifecycleBannerTimer) { clearTimeout(lifecycleBannerTimer); lifecycleBannerTimer = null; }
        if (goalToastTimer) { clearTimeout(goalToastTimer); goalToastTimer = null; }
        closeSource();
    }
    if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
        window.addEventListener('beforeunload', cleanup);
        window.addEventListener('pagehide', cleanup);
    }

    // --- Post-resolution connect step. Runs after resolveProperties()
    //     has populated apiBaseUrl + eventId (either from xiboIC.info()
    //     or by falling back to the raw literal). ---
    function connect() {
        if (!apiBaseUrl) {
            showLifecycleBanner('Configure apiBaseUrl');
            setStatus('disconnected', 'not configured');
            crowdaqLog('error', 'connect-no-api-base-url', {
                rawApiBaseUrl: apiBaseUrlRaw,
                rawEventId: eventIdRaw
            });
            return;
        }
        if (typeof EventSource === 'undefined') {
            setStatus('disconnected', 'no EventSource');
            showErrorPill('EventSource unsupported');
            crowdaqLog('error', 'connect-no-eventsource', {});
            return;
        }
        // Build stream URL. eventId is optional; when empty the backend
        // picks the best live event for the display. Phase-1 default is
        // replay mode (no `live=true`) at speed=10 — a typical 90-min
        // match condenses to ~9 min of bar-TV time, then the recording
        // loops via the `status: 'looping'` transition the backend
        // emits at end-of-file. See docs/contract/openapi.yaml.
        var streamEventId = eventId || 'default';
        url = apiBaseUrl
            + '/events/' + encodeURIComponent(streamEventId) + '/stream'
            + '?speed=' + SPEED_MULTIPLIER;
        crowdaqLog('info', 'connect', { url: url, streamEventId: streamEventId });
        openStream();
    }

    resolveProperties(connect);
})();
